"""Transfer exact official frozen weights with stdlib, curl and existing SSH.

One temporary file at a time; no local package installation. Remote originals
remain read-only. Verification receipts are generated by the frozen downloader.
"""
from pathlib import Path
import argparse,hashlib,json,re,subprocess,time,shutil

ORDER=['qwen35_9b','glm47_flash','nemotron3_nano30b','qwen38_27b','gpt_oss_20b','phi4','gemma4_12b','falcon_h1_34b','mistral_small3','seed_oss_36b']
def digest(p):
 h=hashlib.sha256()
 with p.open('rb') as f:
  for b in iter(lambda:f.read(16<<20),b''):h.update(b)
 return h.hexdigest()
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--root',required=True);ap.add_argument('--socket',required=True);ap.add_argument('--state',type=Path,required=True);a=ap.parse_args();a.state.mkdir(parents=True,exist_ok=True)
 refpath=Path(__file__).resolve().parent.parent/'harness/weights_reference.json';refs=json.loads(refpath.read_text())['models']
 if not re.fullmatch(r'/data/qianru/over-comprehension-v2-[0-9]+',a.root):raise RuntimeError('Unexpected remote task root')
 ssh=['ssh','-S',a.socket,'-o','BatchMode=yes','-o','ConnectTimeout=20','q84453243@192.168.1.105'];nested='ssh -T -o BatchMode=yes -o ConnectTimeout=15 -o StrictHostKeyChecking=yes qianru@10.201.226.77 '
 def remote(code,timeout=300):
  script="python3 -u - <<'PY'\n"+code+"\nPY\n"
  p=subprocess.run(ssh+[nested+'/bin/sh'],input=script.encode(),capture_output=True,timeout=timeout)
  if p.returncode:raise RuntimeError((p.stdout+p.stderr).decode(errors='replace')[-1800:])
  return json.loads(p.stdout.decode().splitlines()[-1])
 prefix='from pathlib import Path\nimport json,os,hashlib,shutil,subprocess,time\nr=Path('+repr(a.root)+')\n'
 manifest_path=a.state/'manifest.json';manifest=json.loads(manifest_path.read_text()) if manifest_path.exists() else []
 for model in ORDER:
  ref=refs[model];modelstart=time.time();print('MODEL_PREPARE',model,flush=True)
  status=remote(prefix+"p=r/'operations/weights-verified.json'\nd=json.loads(p.read_text())['models'];q=json.loads((r/'operations/queue.json').read_text())['models'];print(json.dumps({'verified':d.get("+repr(model)+",{}).get('ok',False),'status':q["+repr(model)+"]['status']}))")
  if status['verified'] or status['status'] in ['finished','failed']:print('MODEL_ALREADY_ACCOUNTED',model,status,flush=True);continue
  # Leave 20GiB free, and stage at most one model ahead if previous caches fill
  # the SSD. Workers evict only this task's re-downloadable weights on finish.
  while True:
   code=prefix+"m="+repr(model)+";ref="+repr(ref)+"\nd=r/'weights'/m;d.mkdir(parents=True,exist_ok=True)\nremaining=sum(i['bytes'] for n,i in ref['files'].items() if not (d/n).exists() or (d/n).stat().st_size!=i['bytes'])\nprint(json.dumps({'free':shutil.disk_usage(r).free,'remaining':remaining}))"
   space=remote(code)
   if space['free']>=space['remaining']+(20<<30):break
   print('WAIT_SSD_SPACE',model,space,flush=True);time.sleep(30)
  for name,info in ref['files'].items():
   if '..' in Path(name).parts or not re.fullmatch(r'[A-Za-z0-9_./+-]+',name):raise RuntimeError('Unsafe frozen filename')
   # Existing large shards may be reused only after their fixed SHA matches.
   code=prefix+"model="+repr(model)+";name="+repr(name)+";info="+repr(info)+";ref="+repr(ref)+"\np=r/'weights'/model/name;p.parent.mkdir(parents=True,exist_ok=True)\nfound=False\nif info.get('sha256'):\n candidates=[p]+[Path('/mnt/nas_ssd/qianru')/x/'hub'/('models--'+ref['repo'].replace('/','--'))/'snapshots'/ref['revision']/name for x in ['npcbank-p0-weights','npcbank-c3-weights']]\n for f in candidates:\n  if not f.exists() or f.stat().st_size!=info['bytes']:continue\n  h=hashlib.sha256()\n  with f.open('rb') as fd:\n   for b in iter(lambda:fd.read(16<<20),b''):h.update(b)\n  if h.hexdigest()!=info['sha256']:continue\n  if f!=p:\n   if p.exists() or p.is_symlink():p.unlink()\n   p.symlink_to(f)\n  found=True;break\nprint(json.dumps({'reused':found}))"
   if remote(code,timeout=1200)['reused']:print('REUSED_PINNED_SHARD',model,name,flush=True);continue
   tmp=a.state/'current.bin';spec=a.state/'current-file.json';entry={'model':model,'name':name,'bytes':info['bytes'],'revision':ref['revision']}
   if spec.exists() and json.loads(spec.read_text())!=entry and tmp.exists():tmp.unlink()
   spec.write_text(json.dumps(entry,indent=2))
   if shutil.disk_usage(a.state).free<info['bytes']-(tmp.stat().st_size if tmp.exists() else 0)+(2<<30):raise RuntimeError('Insufficient local space for one shard')
   url='https://huggingface.co/'+ref['repo']+'/resolve/'+ref['revision']+'/'+name
   print('DOWNLOAD',model,name,info['bytes'],flush=True)
   start=time.time()
   subprocess.run(['curl','--fail','--location','--silent','--show-error','--retry','3','--retry-delay','5','--connect-timeout','15','--max-time','3600','--continue-at','-','--output',str(tmp),url],check=True)
   if tmp.stat().st_size!=info['bytes']:raise RuntimeError('Official download size mismatch '+name)
   expected=digest(tmp)
   if info.get('sha256') and expected!=info['sha256']:raise RuntimeError('Fixed SHA mismatch '+name)
   print('DOWNLOAD_VERIFIED',model,name,'seconds',round(time.time()-start,1),flush=True)
   destination=a.root+'/weights/'+model+'/'+name+'.staging-part'
   start=time.time()
   with tmp.open('rb') as f:
    p=subprocess.run(ssh+[nested+'dd of='+destination+' status=none'],stdin=f,capture_output=True,timeout=3600)
   if p.returncode:raise RuntimeError('SSH transfer failed '+p.stderr.decode(errors='replace')[-1000:])
   code=prefix+"p=Path("+repr(destination)+");out=p.with_name(p.name[:-len('.staging-part')]);expected="+repr(expected)+";size="+repr(info['bytes'])+"\nh=hashlib.sha256()\nwith p.open('rb') as f:\n for b in iter(lambda:f.read(16<<20),b''):h.update(b)\nif p.stat().st_size!=size or h.hexdigest()!=expected:raise RuntimeError('Remote shard digest mismatch')\nif out.is_symlink():out.unlink()\nos.replace(p,out)\nprint(json.dumps({'ok':True,'sha256':expected}))"
   receipt=remote(code,timeout=1200)
   manifest.append({**entry,'repo':ref['repo'],'official_url':url,'sha256':expected,'remote_path':destination[:-len('.staging-part')],'transfer_seconds':round(time.time()-start,1),'verified_unix':time.time()})
   manifest_path.write_text(json.dumps(manifest,indent=2)+'\n');tmp.unlink();print('STAGED',model,name,receipt,flush=True)
  cmd=[a.root+'/.venv/bin/python','harness/h200_download_v2.py','--root',a.root,'--model',model]
  code=prefix+"cmd="+repr(cmd)+"\ne=os.environ.copy();e.update(HF_HUB_OFFLINE='1',TRANSFORMERS_OFFLINE='1',HF_HUB_DISABLE_XET='1')\nwith (r/'logs'/"+repr(model+'-staged-verify.log')+").open('ab') as f:\n p=subprocess.run(cmd,cwd=r/'code',env=e,stdout=f,stderr=subprocess.STDOUT)\nif p.returncode:raise RuntimeError('Final frozen weight verification failed')\nprint(json.dumps({'model':"+repr(model)+",'ready':True}))"
  ready=remote(code,timeout=1800);print('MODEL_WEIGHTS_READY',ready,'seconds',round(time.time()-modelstart,1),flush=True)
 print('ALL_WEIGHT_PREPARATION_COMPLETE',flush=True)
if __name__=='__main__':main()
